(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.28)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.016-t*0.3)*16 + Math.sin(x*0.014+t*0.32)*11;
  const w2x = Math.sin((x+w1x)*0.012+t*0.15)*8;
  const w2y = Math.cos((y+w1y)*0.011-t*0.18)*7;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [120+Math.sin(t*0.5)*90, 60+Math.cos(t*0.35)*40, 0.09, 2.1],
    [360+Math.cos(t*0.45)*80, 50+Math.sin(t*0.55)*45, 0.07, 1.8],
    [80+Math.cos(t*0.6+1)*70, 180+Math.sin(t*0.4+2)*50, 0.11, 2.4],
    [400+Math.sin(t*0.38+3)*60, 190+Math.cos(t*0.5+1)*55, 0.08, 2.0],
    [240+Math.sin(t*0.3+2)*130, 120+Math.cos(t*0.45+1)*80, 0.055, 2.6],
    [180+Math.cos(t*0.42+4)*100, 200+Math.sin(t*0.52)*60, 0.1, 1.6],
    [300+Math.sin(t*0.55+5)*85, 100+Math.cos(t*0.33+3)*65, 0.065, 2.2],
    [240+Math.cos(t*0.28+0.5)*110, 30+Math.sin(t*0.48+2)*50, 0.075, 1.9],
    [50+Math.sin(t*0.65+1.5)*50, 120+Math.cos(t*0.4+4)*70, 0.12, 2.5],
    [430+Math.cos(t*0.5+2.5)*45, 130+Math.sin(t*0.35+1)*60, 0.085, 2.3]
  ];
  let aS=0, iS=0, hS=0;
  for(const [sX,sY,f,sp] of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave=Math.sin(d*f-t*sp);
    const decay=1/(1+d*0.008);
    aS+=wave*decay;
    iS+=Math.sin(d*f*0.7+t*sp*0.5+1.2)*decay;
    hS+=Math.sin(d*f*1.3-t*sp*0.8+2.5)*decay*0.5;
  }
  const act=aS/10, inh=iS/10, harm=hS/10;
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*0.95))/2
    +Math.sin((sx+sy)*0.1+t*2.2)*0.15+Math.sin((sx-sy)*0.08-t*1.8)*0.15
    +Math.sin(sx*0.06+t*1.5)*Math.cos(sy*0.05-t*1.3)*0.1;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*4-t*1.3)+Math.sin(dist*0.035+ang*5-t*1.0)+Math.sin(dist*0.06-ang*2+t*0.7))*0.28;
  const laplacian=Math.sin(sx*0.2)*Math.sin(sy*0.2)+Math.sin(sx*0.15+sy*0.15)*0.7+Math.sin(sx*0.25-sy*0.18)*0.4;
  const rd=act-inh*0.65+harm*0.35+bg*0.25+spiral+laplacian*0.15;
  const reaction=Math.tanh(rd*2.0);
  const cell=Math.tanh((Math.sin(sx*0.13)*Math.sin(sy*0.13)+Math.sin((sx+sy)*0.09+t)*0.4+Math.sin(sx*0.17-t*0.8)*Math.cos(sy*0.14+t*0.6)*0.3)*1.4)*0.25;
  const micro=Math.sin(sx*0.4+t*3)*Math.sin(sy*0.35-t*2.5)*0.08;
  const blend=reaction*0.7+cell*0.22+micro;
  const v=blend*0.5+0.5;
  const edge=Math.abs(reaction)>0.65?1.0:0.85;
  const pulse=0.85+Math.sin(t*0.8)*0.1+Math.sin(reaction*Math.PI*1.5)*0.12;
  const lum=edge*pulse;
  const pal=[
    [6,12,52],[10,35,82],[14,68,105],[18,105,120],[30,148,128],
    [85,175,120],[165,195,85],[210,190,60],[215,150,55],
    [205,105,65],[175,62,72],[125,35,68],[70,22,60],[35,15,55],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum)|0
  ];
}
